function point(x,y,z=0){return{x:(x-y)*.82,y:(x+y)*.41-z};}
function project(x,y,z=0){const p=point(x,y,z),c=point(camera.x,camera.y);return{x:width/2+(p.x-c.x)*zoom,y:height/2+(p.y-c.y)*zoom};}
function unproject(x,y){const c=point(camera.x,camera.y),px=(x-width/2)/zoom+c.x,py=(y-height/2)/zoom+c.y;return{x:(px/.82+py/.41)/2,y:(py/.41-px/.82)/2};}
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function powered(d){return d.type==='isp'||d.type==='patch'||d.type==='wall'||(d.type==='pc'?state.pcPower:state.ups);}
function endpoint(device,port){return{device,port};}
const same=(a,b)=>a.device===b.device&&a.port===b.port;
function cableAt(p){return state.cables.find(c=>same(c.a,p)||same(c.b,p));}
function otherEnd(c,p){return same(c.a,p)?c.b:c.a;}
function connected(a,ap,b,bp){return state.cables.some(c=>same(c.a,endpoint(a,ap))&&same(c.b,endpoint(b,bp))||same(c.b,endpoint(a,ap))&&same(c.a,endpoint(b,bp)));}
const expected=[['ISP','GE0','RTR-01','WAN'],['RTR-01','LAN','FW-01','WAN'],['FW-01','LAN','CORE-01','Gi0/1'],['CORE-01','Gi0/2','SW-01','Gi0/1'],['SW-01','Fa0/1','PATCH-01','P1'],['WALL-01','J1','PC-01','eth0']];
function wiringDone(){return expected.every(l=>connected(...l));}
function syncSwitch(id){const c=state.config[id],d=c.cisco;if(!d)return;const r=d.running,u=r.interfaces['GigabitEthernet0/1'],a=r.interfaces['FastEthernet0/1'];c.vlan10=!!r.vlans[10];c.routing=r.routing;c.svi=r.interfaces.Vlan10?.address||'';c.saved=!CiscoCLI.dirty(d);c.trunk=!!u&&u.mode==='trunk'&&CiscoCLI.carries(u,10);c.accessMode=!!a&&a.mode==='access'&&!a.shutdown;c.accessVlan=a?.access||1;}
function portEnabled(id,port){const i=state.config[id]?.cisco?.running.interfaces[CiscoCLI.nameOf(port)];return !i?.shutdown;}
function physicalUp(id,port){const ep=endpoint(id,port),c=cableAt(ep);if(!c)return false;const peer=otherEnd(c,ep);return powered(byId[id])&&powered(byId[peer.device])&&portEnabled(id,port)&&portEnabled(peer.device,peer.port);}
function vlanActive(id,v){const d=state.config[id].cisco;return d.physical.some(name=>{const port=CiscoCLI.short(name),i=d.running.interfaces[name];if(!physicalUp(id,port))return false;const ep=endpoint(id,port),peer=otherEnd(cableAt(ep),ep),other=state.config[peer.device]?.cisco?.running.interfaces[CiscoCLI.nameOf(peer.port)];const trunk=i.mode==='trunk'||i.mode.startsWith('dynamic')&&other?.mode==='trunk';return trunk?CiscoCLI.carries(i,v)&&(!other||CiscoCLI.carries(other,v))&&(!other||((i.native===v)===(other.native===v))):i.access===v;});}
function coreConfigured(){const c=state.config['CORE-01'],r=c.cisco.running,i=r.interfaces.Vlan10,u=r.interfaces['GigabitEthernet0/2'];return c.vlan10&&!!i&&!i.shutdown&&i.address==='10.10.10.1'&&i.mask==='255.255.255.0'&&u.mode!=='access'&&CiscoCLI.carries(u,10);}
function coreOperational(){return coreConfigured()&&vlanActive('CORE-01',10);}
function switchOperational(){const c=state.config['SW-01'];return c.vlan10&&c.trunk&&c.accessMode&&c.accessVlan===10;}
function coreReady(){return coreConfigured()&&state.config['CORE-01'].routing&&state.config['CORE-01'].saved;}
function switchReady(){return switchOperational()&&state.config['SW-01'].saved;}
function pcReady(){return state.pc.ip==='10.10.10.21'&&state.pc.mask==='255.255.255.0'&&state.pc.gateway==='10.10.10.1';}
function linkLayerReady(){return state.ups&&state.pcPower&&permanentReady()&&expected.slice(3).every(l=>connected(...l)&&physicalUp(l[0],l[1])&&physicalUp(l[2],l[3]));}
