function blocked(x,y){return blockedAt(x,y,locationKey());}
function move(dx,dy){moveActor(state.player,dx,dy,locationKey());}
const routeCache=new Map();
function findPath(from,target,key=locationKey(),access='staff'){const size=22,start={x:Math.round(from.x/size),y:Math.round(from.y/size)},end={x:Math.round(target.x/size),y:Math.round(target.y/size)};const nodeKey=n=>n.x+','+n.y,cacheKey=key+'|'+access+'|'+nodeKey(start)+'|'+nodeKey(end);if(routeCache.has(cacheKey))return routeCache.get(cacheKey).map(p=>({...p}));let open=[{...start,g:0,f:0}],seen=new Map([[nodeKey(start),0]]),parents=new Map(),found=null;
 for(let iter=0;open.length&&iter<7000;iter++){open.sort((a,b)=>a.f-b.f);const n=open.shift();if(Math.abs(n.x-end.x)+Math.abs(n.y-end.y)<=1){found=n;break;}for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const q={x:n.x+dx,y:n.y+dy};if(blockedAt(q.x*size,q.y*size,key,access))continue;const g=n.g+1,k=nodeKey(q);if(seen.has(k)&&seen.get(k)<=g)continue;seen.set(k,g);parents.set(k,n);open.push({...q,g,f:g+Math.abs(q.x-end.x)+Math.abs(q.y-end.y)});}}
 if(!found)return null;const result=[];let n=found;while(nodeKey(n)!==nodeKey(start)){result.unshift({x:n.x*size,y:n.y*size});n=parents.get(nodeKey(n));if(!n)break;}if(routeCache.size>250)routeCache.delete(routeCache.keys().next().value);routeCache.set(cacheKey,result.map(p=>({...p})));return result;
}
function route(target){const result=findPath(state.player,target);if(!result){toast('無法走到那裡，請選擇走道或設備前方。');return false;}path=result;return true;}
function approach(d){return{x:d.x+d.w/2,y:d.y+d.d+50};}
