function nearest(){return definitions.filter(near).sort((a,b)=>dist(state.player,approach(a))-dist(state.player,approach(b)))[0];}
function inspect(id){if(!isMainFloor())return toast('施工設備在門診大樓 1F，可使用園區導覽返回。');pendingTalk=null;const d=byId[id];if(!d)return;if(!near(d)){closeInspector();pendingInspect=id;if(!route(approach(d)))pendingInspect=null;else toast(`正在走向 ${d.name}。`);return;}selected=id;keys.clear();path=[];pendingInspect=null;if(d.x<720&&d.y<640)state.visited=true;renderInspector();refreshHUD();}
