function initHospital(){state.location=state.location||{building:'main',floor:1};const info=floorInfo();state.location={building:info.id,floor:info.floor};state.hospital=state.hospital||{scenes:{}};state.hospital.scenes??={};for(const s of Object.values(state.hospital.scenes))HospitalLife.ensureScene(s);currentHospital();if(blockedAt(state.player.x,state.player.y,locationKey()))state.player={x:790,y:525};camera={...state.player};}
function currentHospital(){const k=locationKey();if(!Array.isArray(state.hospital.scenes[k]?.agents))state.hospital.scenes[k]=HospitalLife.create(state.location);return HospitalLife.ensureScene(state.hospital.scenes[k]);}
const otherFloorCache=new Map();
function floorObjects(key){if(key==='main:1')return{walls:[...walls,...clinicalPartitions],objects:[...definitions,...furniture]};if(otherFloorCache.has(key))return otherFloorCache.get(key);const [building,n]=key.split(':'),info=HospitalLife.info({building,floor:+n}),ward=info.theme==='ward';let objects=[{x:1235,y:735,w:205,d:54,h:81,type:'registration'},{x:1020,y:830,w:110,d:32,h:45,type:'seats'},{x:1020,y:930,w:110,d:32,h:45,type:'seats'},{x:1365,y:870,w:50,d:50,h:55,type:'plant'},{x:985,y:700,w:30,d:25,h:68,type:'queue'},{x:630,y:550,w:62,d:38,h:65,type:'sink'}];
 if(ward){for(let i=0;i<4;i++){const x=i%2?420:80,y=i<2?130:405;objects.push({x,y,w:150,d:65,h:33,type:'bed',label:`${info.floor}0${i+1} 病床`,profile:HospitalPeople.makePerson(HospitalLife.buildings.findIndex(b=>b.id===building)*200+info.floor*30+80+i,'inpatient')});objects.push({x:x+150,y:y+32,w:28,d:28,h:110,type:'iv'});}}else objects.push({x:70,y:180,w:130,d:60,h:48,type:'exam'},{x:450,y:180,w:130,d:60,h:48,type:'exam'},{x:90,y:520,w:95,d:44,h:90,type:'cabinet'},{x:1200,y:410,w:150,d:65,h:33,type:'bed',label:info.theme==='emergency'?'急診觀察床':'觀察床'},{x:1360,y:420,w:40,d:32,h:92,type:'monitor'});
 if(info.theme==='pediatrics')objects.push({x:1050,y:180,w:100,d:95,h:30,type:'play'});
 const result={walls:[...walls,...(ward?[]:[{x:350,y:32,w:12,d:280},{x:350,y:470,w:12,d:170}])],objects};otherFloorCache.set(key,result);return result;}
function blockedAt(x,y,key,access='staff'){if(access==='public'&&HospitalLife.restrictedArea(key,x,y))return true;if(x<42||x>1450||y<42||y>1010)return true;const r=13,w=floorObjects(key);return [...w.walls,...w.objects].some(o=>x>o.x-r&&x<o.x+o.w+r&&y>o.y-r&&y<o.y+o.d+r);}
