function switchLocation(building,floor){const next=HospitalLife.info({building,floor});if(next.key===locationKey()){$('#dialog').close();return;}state.mapPositions??={};state.mapPositions[locationKey()]={...state.player};path=[];pendingInspect=null;pendingTalk=null;cableStart=null;closeInspector();state.location={building:next.id,floor:next.floor};const p=state.mapPositions[next.key]||{x:790,y:525};state.player=blockedAt(p.x,p.y,next.key)?{x:790,y:525}:p;camera={...state.player};currentHospital();talkingPersonId=null;$('#dialog').close();refreshHUD();refreshHospitalUI();save();toast(`已搭乘園區接駁／電梯到 ${next.name} ${next.floor}F。`);}
function showCampus(){talkingPersonId=null;showDialog(`<span class="eyebrow">RENHE HOSPITAL / CAMPUS</span><h2>選擇院區與樓層</h2><p>每個樓層有自己的醫護人員、病患和動線。電梯／園區接駁可帶你前往；資訊室施工設備位於門診大樓 1F。</p><div class="campus-grid">${HospitalLife.buildings.map(b=>`<article><h3>${b.name}</h3><p>${{main:'掛號、一般門診與資訊室',children:'親子候診、兒科門診與兒童病房',ward:'住院服務、探病與病房',emergency:'急診登記、檢傷報到與觀察'}[b.id]}</p>${b.floors.map(f=>`<button class="${locationKey()===b.id+':'+f.number?'primary':'secondary'} wide" data-building="${b.id}" data-floor="${f.number}">${f.number}F · ${f.name}${locationKey()===b.id+':'+f.number?'（目前）':''}</button>`).join('')}</article>`).join('')}</div><p>本版用電梯／接駁選單跨樓層，沒有模擬完整戶外道路、實體電梯車廂或醫療診斷。</p>`);$('#dialog').classList.add('campus-dialog');$$('[data-building]').forEach(b=>b.onclick=()=>switchLocation(b.dataset.building,+b.dataset.floor));}
function showHospitalActivity(){const s=currentHospital(),stats=HospitalLife.stats(s);talkingPersonId=null;showDialog(`<span class="eyebrow">LIVE HOSPITAL / ${esc(floorInfo().name)}</span><h2>院區正在發生的事</h2><div id="hospital-activity"><p>掛號／登記 ${stats.registration} 人 · 報到／候診 ${stats.waiting} 人 · 診間 ${stats.consulting} 人 · 本樓層完成 ${stats.completed} 次</p><div class="activity-people">${s.agents.filter(a=>a.phase!=='cooldown').map(a=>`<div>${HospitalPeople.portrait(a.profile)}<span><strong>${a.profile.name}</strong><small>${a.profile.role} · ${HospitalLife.phaseLabel(s,a)}</small></span></div>`).join('')}</div><h3>流程紀錄</h3>${s.logs.slice(-12).reverse().map(l=>`<p>#${l.id} ${esc(l.name)}：${esc(l.message)}</p>`).join('')||'<p>病患正在依動線移動；完成掛號、報到或看診時會留下紀錄。</p>'}</div>`);}
function refreshHospitalUI(){const info=floorInfo(),s=currentHospital(),n=HospitalLife.stats(s);$('#campus-button').textContent=`${info.name} ${info.floor}F ▾`;$('#hospital-live').textContent=`${info.name} ${info.floor}F · 現場 ${lifeMapPeople().length} 人 · 掛號 ${n.registration} · 候診 ${n.waiting} · ${s.theme==='ward'?'入院服務':'看診'} ${n.consulting} · 完成 ${n.completed}`;$('#hospital-live').title='點選查看病患與流程紀錄';$('.scene-caption small').textContent=info.name+' / '+info.floor+'F / '+info.floorName;$('.compass span').textContent=info.name+' '+info.floor+'F';}
function updateHospital(dt){currentHospital();for(const [key,scene]of Object.entries(state.hospital.scenes)){HospitalLife.tick(scene,dt,{talking:key===locationKey()&&$('#dialog').open?talkingPersonId:null,findPath:(a,p)=>findPath(a,p,key,'public'),move:(a,dx,dy)=>moveActor(a,dx,dy,key,'public')});}teamUiClock+=dt;if(teamUiClock>.6){teamUiClock=0;refreshHospitalUI();updateTeamUI();scheduleSave();}}
function lifeMapPeople(){const s=currentHospital(),list=s.agents.filter(a=>a.phase!=='cooldown').map(a=>({id:a.id,x:a.x,y:a.y,profile:a.profile,visit:a.visit,asking:a.phase==='wayfinding',role:a.child?'child':a.kind,stage:HospitalLife.phaseLabel(s,a),walking:!!a.path?.length,draw:a.kind!=='inpatient'}));if(isMainFloor()){list.push(...crewMapPeople(),{id:'desk-nurse',x:1160,y:57,profile:HospitalPeople.profiles.deskNurse,role:'nurse',stage:'護理站值班',draw:false},{id:'bed-a',x:1230,y:540,profile:HospitalPeople.profiles.bedA,role:'inpatient',stage:'住院休養',draw:false},{id:'bed-b',x:1320,y:265,profile:HospitalPeople.profiles.bedB,role:'inpatient',stage:'住院休養',draw:false});}for(const a of s.agents.filter(a=>a.child&&a.phase!=='cooldown'))list.push({id:a.id+'-guardian',x:a.x+24,y:a.y+12,profile:{...(a.guardian||HospitalPeople.makePerson((a.ticket||0)+250,'guardian')),name:a.profile.name.slice(0,1)+(a.guardian||HospitalPeople.makePerson((a.ticket||0)+250,'guardian')).name.slice(1)},role:'guardian',stage:'陪同兒童就診',walking:!!a.path?.length,draw:true});return list;}
function personAt(x,y){return peopleHitTargets.slice().sort((a,b)=>b.x+b.y-a.x-a.y).find(p=>{const a=project(p.x,p.y,38);return Math.abs(x-a.x)<18*zoom+5&&Math.abs(y-a.y)<35*zoom+4;});}
function nearestPerson(){return lifeMapPeople().filter(p=>dist(state.player,p)<95).sort((a,b)=>dist(state.player,a)-dist(state.player,b))[0];}
function interaction(){const human=nearestPerson(),d=isMainFloor()?nearest():null,personDistance=human?dist(state.player,human):Infinity,deviceDistance=d?dist(state.player,approach(d)):Infinity;if(human&&personDistance<deviceDistance)return{kind:'person',person:human};if(d)return{kind:'device',device:d};if(dist(state.player,{x:810,y:550})<90)return{kind:'campus'};return null;}
function showPerson(p){const info=floorInfo(),scene=currentHospital(),dialogue=HospitalDialogue.conversation(scene,p);showDialog(`<div class="conversation">${HospitalPeople.portrait(p.profile)}<div><span class="eyebrow">${esc(info.name)} ${info.floor}F</span><h2>${esc(p.profile.name)}</h2><p>${esc(p.profile.role)} · ${esc(dialogue.detail||p.stage)}</p></div></div><div id="dialogue-reply" class="speech-bubble">${esc(dialogue.opener)}</div><div class="dialogue-options">${dialogue.options.map(o=>`<button class="secondary" data-talk="${o.id}">${esc(o.label)}</button>`).join('')}${p.role==='crew'?`<button class="primary" id="assign-from-talk">我要指派工作</button>`:''}<button class="secondary" id="end-talk">${dialogue.visitor?'先不打擾你了':'回頭聊'}</button></div>`);talkingPersonId=p.id;$$('[data-talk]').forEach(b=>b.onclick=()=>{const answer=dialogue.reply(b.dataset.talk);$('#dialogue-reply').textContent=p.profile.name+'：'+answer;if(b.dataset.talk==='guide'){$('#dialogue-reply').innerHTML=`<div class="player-guidance">你：${esc(dialogue.route)}</div><div>${esc(p.profile.name)}：${esc(answer)}</div>`;b.disabled=true;b.textContent='✓ 已告知公共路線';refreshHUD();scheduleSave();}});$('#assign-from-talk')?.addEventListener('click',()=>{showTeam('crew');const card=$(`[data-assignment="${p.member.id}"]`)?.closest('.crew-card');if(card){card.classList.add('focused-member');card.scrollIntoView({block:'center'});}});$('#end-talk').onclick=()=>$('#dialog').close();}
function renderNamedPerson(p){if(p.draw===false)return;if(p.asking&&dist(state.player,p)<250)text(`？ ${p.visit?.room||'診間'}在哪裡？`,p.x,p.y,118,'#efc397',9);HospitalPeople.draw(ctx,point(p.x,p.y),p.profile,{walking:p.walking,phase:performance.now()/130,scale:p.role==='child'?.82:1.12,tool:p.role==='crew'});if(p.role==='crew'||p.role==='doctor'||dist(state.player,p)<230){text(`${p.profile.name}${p.role==='doctor'?' 醫師':''}`,p.x,p.y,p.role==='child'?67:83,p.role==='crew'?'#d8edac':'#eff0dd',9);if(dist(state.player,p)<150||p.role==='crew')text(p.stage,p.x,p.y,99,'#bacfcb',7);}}
function renderOtherFloor(){const info=floorInfo(),ward=info.theme==='ward',child=info.theme==='pediatrics';floorRect(0,0,1500,1060,child?'#d6d6bd':'#bdccc7','#8aa6a6');floorRect(734,32,166,996,child?'#e0d6bd':'#ced4cb',null);floorRect(32,32,688,608,ward?'#c2d6cf':child?'#cddcce':'#bad0cd',null);ctx.globalAlpha=.2;for(let x=40;x<1480;x+=60)line3([[x,32,0],[x,1028,0]],'#81999c',.6);for(let y=40;y<1040;y+=60)line3([[32,y,0],[1468,y,0]],'#81999c',.6);ctx.globalAlpha=1;floorRect(785,100,10,820,child?'#c89993':'#75a3a1',null);for(const w of floorObjects(locationKey()).walls)box(w.x,w.y,w.w,w.d,55,'#e0e6db','#a1b8b7','#b9ccc4');text(`${info.name} ${info.floor}F`,790,540,1,'#728f92',20);text(info.floorName,790,575,1,'#7d9898',13);text(ward?'病房照護區':HospitalLife.clinics(currentHospital())[0].room+' '+HospitalLife.clinics(currentHospital())[0].department,180,420,1,'#729294',18);text(ward?'護理巡視區':HospitalLife.clinics(currentHospital())[1].room+' '+HospitalLife.clinics(currentHospital())[1].department,550,420,1,'#729294',18);text(info.theme==='emergency'?'急診登記／檢傷報到':'掛號／報到',1230,900,1,'#6c898b',16);text('電梯／園區接駁 E',810,620,1,'#648e89',13);}
function renderFloorObject(o){if(o.type==='play'){box(o.x,o.y,o.w,o.d,4,'#9ec3b3','#789b91','#8cafa1');for(let i=0;i<5;i++)box(o.x+10+i*16,o.y+20+(i%2)*18,15,15,18,['#d7a18a','#e0c088','#8bb8bc','#b2a0c5','#b9c986'][i]);text('親子遊戲角',o.x+50,o.y+o.d+15,2,'#8a8d76',11);}else if(['sink','cabinet','exam','registration','wheelchair','queue'].includes(o.type))renderClinicalProp(o);else renderFurniture(o);}

function cliKey(e,id){if(id==='PC-01'||!consoleSession)return false;const d=state.config[id].cisco,s=consoleSession;if(e.key==='Tab'){e.preventDefault();e.target.value=CiscoCLI.complete(e.target.value,s);return true;}if(e.key==='?'){e.preventDefault();const prefix=e.target.value;runCommand(id,prefix+'?');$('#command-input').value=prefix;return true;}if(e.ctrlKey&&['z','c'].includes(e.key.toLowerCase())){e.preventDefault();if(s.pending){s.pending=null;toast('已取消目前確認。');}else{s.mode='priv';s.iface=null;s.range=null;}renderInspector();$('#command-input')?.focus();return true;}return false;}
initTeam();initHospital();updateTeamUI();refreshHospitalUI();$('#team-button').onclick=()=>showTeam();$('#team-chip').onclick=()=>showTeam('crew');$('#campus-button').onclick=showCampus;$('#hospital-live').onclick=showHospitalActivity;$('#dialog').addEventListener('close',()=>talkingPersonId=null);
new ResizeObserver(resize).observe($('#viewport'));refreshHUD();setZoom(zoom);requestAnimationFrame(update);
